--
-- Table structure for table `notifications`
--

DROP TABLE IF EXISTS `notifications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notifications` (
  `notification_id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `user_id` bigint NOT NULL,
  `event_id` bigint DEFAULT NULL,
  `request_id` bigint DEFAULT NULL,
  `notification_type` enum('MOVE_REQUEST','MOVE_RESPONSE','REMINDER','EV_OVERSTAY','EVENT_RESOLVED') NOT NULL,
  `title` varchar(100) NOT NULL,
  `body` text NOT NULL,
  `sent_at` datetime(6) NOT NULL,
  PRIMARY KEY (`notification_id`),
  KEY `fk_notifications_user` (`user_id`),
  KEY `fk_notifications_event` (`event_id`),
  KEY `fk_notifications_request` (`request_id`),
  CONSTRAINT `fk_notifications_event` FOREIGN KEY (`event_id`) REFERENCES `parking_events` (`event_id`),
  CONSTRAINT `fk_notifications_request` FOREIGN KEY (`request_id`) REFERENCES `move_requests` (`request_id`),
  CONSTRAINT `fk_notifications_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=143 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

