--
-- Table structure for table `parking_events`
--

DROP TABLE IF EXISTS `parking_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `parking_events` (
  `event_id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `session_id` bigint NOT NULL,
  `vehicle_id` bigint NOT NULL,
  `zone_id` bigint DEFAULT NULL,
  `event_type` enum('BAD_PARKING','DISABLED_ZONE_VIOLATION','DOUBLE_PARKING','EV_OVERSTAY','OUT_OF_ZONE','ETC') NOT NULL,
  `reason` text,
  `violation_ratio` int DEFAULT NULL,
  `event_status` enum('DETECTED','DISMISSED','NEED_ADMIN','REQUESTED','RESOLVED') NOT NULL,
  `detected_at` datetime(6) NOT NULL,
  `resolved_at` datetime(6) DEFAULT NULL,
  `incident_id` varchar(36) DEFAULT NULL,
  `publication_revision` int DEFAULT NULL,
  `rule_code` varchar(40) DEFAULT NULL,
  `physical_vehicle_id` varchar(36) DEFAULT NULL,
  `entry_attempt_id` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`event_id`),
  UNIQUE KEY `uk_parking_events_incident_id` (`incident_id`),
  KEY `fk_parking_events_session` (`session_id`),
  KEY `fk_parking_events_vehicle` (`vehicle_id`),
  KEY `fk_parking_events_zone` (`zone_id`),
  CONSTRAINT `fk_parking_events_session` FOREIGN KEY (`session_id`) REFERENCES `parking_sessions` (`session_id`),
  CONSTRAINT `fk_parking_events_vehicle` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`vehicle_id`),
  CONSTRAINT `fk_parking_events_zone` FOREIGN KEY (`zone_id`) REFERENCES `parking_zones` (`zone_id`)
) ENGINE=InnoDB AUTO_INCREMENT=144 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

