--
-- Table structure for table `parking_sessions`
--

DROP TABLE IF EXISTS `parking_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `parking_sessions` (
  `session_id` bigint NOT NULL AUTO_INCREMENT,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `vehicle_id` bigint NOT NULL,
  `zone_id` bigint DEFAULT NULL,
  `recognized_plate_number` varchar(20) NOT NULL,
  `entry_attempt_id` varchar(100) DEFAULT NULL,
  `entry_time` datetime(6) NOT NULL,
  `parked_at` datetime(6) DEFAULT NULL,
  `exit_time` datetime(6) DEFAULT NULL,
  `idempotency_key` varchar(100) DEFAULT NULL,
  `context_revision` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`session_id`),
  UNIQUE KEY `uk_parking_sessions_idempotency_key` (`idempotency_key`),
  KEY `fk_parking_sessions_vehicle` (`vehicle_id`),
  KEY `fk_parking_sessions_zone` (`zone_id`),
  CONSTRAINT `fk_parking_sessions_vehicle` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles` (`vehicle_id`),
  CONSTRAINT `fk_parking_sessions_zone` FOREIGN KEY (`zone_id`) REFERENCES `parking_zones` (`zone_id`)
) ENGINE=InnoDB AUTO_INCREMENT=247 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

